'use strict';

// Generated by Clause Sonnet 5.5 / Refactored by HellXCore
// The media keys on Linux (launch.media): pause, play, next, previous go to the media player over
// MPRIS (D-Bus: Spotify, Firefox, VLC, Elisa, mpv with a plugin...), the volume goes through
// PipeWire (wpctl) or PulseAudio (pactl). Keys cannot be typed into a Wayland session, so this
// talks to the players instead.

const { execFile } = require('node:child_process');
const { Bus } = require('./dbus-mini');

const MPRIS = 'org.mpris.MediaPlayer2.';
const PLAYER = { path: '/org/mpris/MediaPlayer2', iface: 'org.mpris.MediaPlayer2.Player' };
const CALL_MS = 1500; // a player that does not answer in this time is left out

const player = (destination, member, args) => ({ destination, ...PLAYER, member, args, timeout: CALL_MS });

async function status(bus, name) {
  try {
    const [value] = await bus.call({
      destination: name, path: PLAYER.path, iface: 'org.freedesktop.DBus.Properties', member: 'Get',
      args: [['s', PLAYER.iface], ['s', 'PlaybackStatus']], timeout: CALL_MS,
    });
    return String(value); // Playing | Paused | Stopped
  } catch {
    return null; // not answering: not a player to send to
  }
}

// [{ name, status }] of the players on the bus, the playing ones first
async function players(bus) {
  const [names] = await bus.call({
    destination: 'org.freedesktop.DBus', path: '/org/freedesktop/DBus', iface: 'org.freedesktop.DBus', member: 'ListNames',
  });
  const found = await Promise.all(names.filter((n) => n.startsWith(MPRIS)).map(async (name) => ({ name, status: await status(bus, name) })));
  const rank = { Playing: 0, Paused: 1, Stopped: 2 };
  return found.filter((p) => p.status).sort((a, b) => rank[a.status] - rank[b.status]);
}

// Which players an action goes to, and what to tell them:
//   pause: everything that is playing; play: nothing if something already plays, else a paused
//   player (the first listed); next / previous: the one playing, else the first
function plan(action, list) {
  const playing = list.filter((p) => p.status === 'Playing');
  switch (action) {
    case 'pause':
      return playing.map((p) => [p.name, 'Pause']);
    case 'play': {
      if (playing.length) return [];
      const one = list.find((p) => p.status === 'Paused') || list[0];
      return one ? [[one.name, 'Play']] : [];
    }
    case 'next':
    case 'previous': {
      const one = playing[0] || list[0];
      return one ? [[one.name, action === 'next' ? 'Next' : 'Previous']] : [];
    }
    default:
      return [];
  }
}

const run = (cmd, args) => new Promise((resolve, reject) => {
  execFile(cmd, args, { timeout: 4000 }, (err, out) => (err ? reject(err) : resolve(String(out))));
});

// the volume: PipeWire's wpctl, else PulseAudio's pactl (what PipeWire answers to as well)
const VOLUME = {
  volup: [['wpctl', ['set-volume', '-l', '1.0', '@DEFAULT_AUDIO_SINK@', '10%+']], ['pactl', ['set-sink-volume', '@DEFAULT_SINK@', '+10%']]],
  voldown: [['wpctl', ['set-volume', '@DEFAULT_AUDIO_SINK@', '10%-']], ['pactl', ['set-sink-volume', '@DEFAULT_SINK@', '-10%']]],
  mute: [['wpctl', ['set-mute', '@DEFAULT_AUDIO_SINK@', 'toggle']], ['pactl', ['set-sink-mute', '@DEFAULT_SINK@', 'toggle']]],
};

async function volume(action, exec = run) {
  for (const [cmd, args] of VOLUME[action]) {
    try {
      await exec(cmd, args);
      return true;
    } catch (err) {
      if (err.code !== 'ENOENT') return false; // it is there and failed
    }
  }
  return false;
}

// true if something reacted
async function media(action, { connect = () => Bus.connect(), exec = run } = {}) {
  if (VOLUME[action]) return volume(action, exec);
  if (!['pause', 'play', 'next', 'previous'].includes(action)) return false;
  let bus;
  try {
    bus = await connect();
    const steps = plan(action, await players(bus));
    if (!steps.length) return false;
    const results = await Promise.allSettled(steps.map(([name, member]) => bus.call(player(name, member, []))));
    return results.some((r) => r.status === 'fulfilled');
  } catch {
    return false;
  } finally {
    bus?.close();
  }
}

module.exports = { media, plan, players, volume };
